160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredOwnerFields(ownerFieldsDto);
164	        LocalDate suppliedOrDefaultDate =
165	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
166	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
167	        rejectDailyLimitExceeded(registrationDate);
168	        rejectCityAtCapacity(ownerFieldsDto.getCity());
169	        HttpHeaders headers = new HttpHeaders();
170	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
171	        validatePostcode(owner.getCity(), owner.getPostcode());
172	        owner.setAddress(normalizeAddress(owner.getAddress()));
173	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
174	        owner.setTelephone(normalizedTelephone);
175	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
176	        owner.setEmail(normalizeEmail(owner.getEmail()));
177	        rejectDuplicateIdentity(owner);
178	        owner.setRegistrationDate(registrationDate);
179	        owner.setCustomerCode(
180	            generateCustomerCode(owner.getPostcode(), owner.getCity(), normalizedTelephone, owner.getLastName()));
181	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        this.clinicService.saveOwner(owner);
184	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
185	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
186	        OwnerDto ownerDto = toOwnerDto(owner);
187	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
