285	
286	    /**
287	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
288	     * offending field is collected so the caller learns exactly which values must be supplied.
289	     *
290	     * @param ownerFieldsDto the submitted owner payload
291	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
292	     *         telephone is missing or blank
293	     */
294	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> missingFields = new ArrayList<>();
296	        if (isBlank(ownerFieldsDto.getFirstName())) {
297	            missingFields.add("firstName");
298	        }
299	        if (isBlank(ownerFieldsDto.getLastName())) {
300	            missingFields.add("lastName");
301	        }
302	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
303	            missingFields.add("address");
304	        }
305	        if (isBlank(ownerFieldsDto.getCity())) {
306	            missingFields.add("city");
307	        }
308	        if (isBlank(ownerFieldsDto.getTelephone())) {
309	            missingFields.add("telephone");
310	        }
311	        if (!missingFields.isEmpty()) {
312	            throw new MissingOwnerFieldsException(missingFields);
313	        }
314	    }
315	
316	    private boolean isBlank(String value) {
317	        return value == null || value.isBlank();
318	    }
319	
320	    /**
321	     * Counts the existing owners who, before this create, already share the given first and last name.
322	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
323	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
324	     * case or spacing still count as the same name.
325	     *
326	     * @param firstName the first name of the owner being created
327	     * @param lastName the last name of the owner being created
328	     * @return the number of existing owners sharing both names (zero when none)
329	     */
330	    private int countNamesakes(String firstName, String lastName) {
331	        String first = normalizeHouseholdField(firstName);
332	        String last = normalizeHouseholdField(lastName);
333	        return (int) this.clinicService.findAllOwners().stream()
334	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
335	                && normalizeHouseholdField(existing.getLastName()).equals(last))
336	            .count();
337	    }
338	
339	    /**
340	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
341	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
342	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
343	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
344	     * more owners the create is rejected as a conflict.
345	     *
346	     * @param city the city of the owner being created
347	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
348	     */
349	    /**
350	     * Rejects an owner create once the maximum number of owners have already been registered on the
351	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
352	     * which is always a business day (a weekend effective date is rolled forward to the following
353	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
354	     * business day the create is rejected as too many requests. Because a weekend effective date is
355	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
356	     *
357	     * @param businessDay the adjusted business day the owner being created would be registered on
358	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
359	     */
360	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
361	        long ownersOnDay = this.clinicService.findAllOwners().stream()
362	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
363	            .count();
364	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
365	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
366	        }
367	    }
368	
369	    /**
370	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
371	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
372	     * was supplied on the request or defaulted to the server's current date.
373	     *
374	     * @param date the effective registration date (supplied or defaulted)
375	     * @return the same date when it is a weekday, otherwise the following Monday
376	     */
377	    /**
378	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
379	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
380	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
381	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
382	     *
383	     * @return {@code true} when more than the threshold number of owners are already registered on
384	     *         today's business day, otherwise {@code false}
385	     */
386	    private boolean isBulkSignupWarningActive() {
387	        LocalDate today = toBusinessDay(LocalDate.now());
388	        long ownersToday = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> today.equals(existing.getRegistrationDate()))
390	            .count();
391	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
392	    }
393	
394	    private LocalDate toBusinessDay(LocalDate date) {
395	        return switch (date.getDayOfWeek()) {
396	            case SATURDAY -> date.plusDays(2);
397	            case SUNDAY -> date.plusDays(1);
398	            default -> date;
399	        };
400	    }
401	
402	    private void rejectCityAtCapacity(String city) {
403	        String normalizedCity = normalizeHouseholdField(city);
404	        long ownersInCity = this.clinicService.findAllOwners().stream()
405	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
406	            .count();
407	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
408	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
409	        }
410	    }
411	
412	    /**
413	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
414	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
415	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
416	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
417	     * sequence number; two owners resolve to the same code only when they share a region and produce the
418	     * same telephone-and-last-name hash.
419	     *
420	     * @param postcode the owner's postcode, used first to derive the region
421	     * @param city the owner's city, used to derive the region when the postcode maps to none
422	     * @param normalizedTelephone the owner's normalized (E.164) telephone
423	     * @param lastName the owner's last name
424	     * @return the formatted customer code
425	     */
426	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
427	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
428	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
429	        return region + "-" + hash8;
430	    }
431	
432	    /**
433	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
434	     * customerCode is the owner's customer code and YY is the last two digits of the
435	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
436	     *
437	     * @param customerCode the owner's customer code
438	     * @param registrationDate the owner's registration date
439	     * @return the formatted membership number
440	     */
441	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
442	        String yy = String.format("%02d", registrationDate.getYear() % 100);
443	        return customerCode + "-M" + yy;
444	    }
445	
446	    /**
447	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
448	     * country calling code. Australia ('+61') uses 9 national digits and the North American
449	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
450	     * E.164 length (8 to 15 digits overall).
451	     */
452	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
453	        java.util.Map.of("61", 9, "1", 10);
454	
455	    /**
456	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
457	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
458	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
459	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
460	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
461	     * E.164 string is what gets stored and returned.
462	     *
463	     * @param telephone the raw telephone value from the request
464	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
465	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
466	     *         national number has the wrong length for its country code
467	     */
468	    private String normalizeTelephone(String telephone) {
469	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
470	        String e164;
471	        if (cleaned.startsWith("+")) {
472	            e164 = cleaned;
473	        } else {
474	            String national = cleaned;
475	            if (national.startsWith("0")) {
476	                national = national.substring(1);
477	            }
478	            e164 = "+61" + national;
479	        }
480	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
481	            throw new InvalidOwnerFieldsException(List.of("telephone"));
482	        }
483	        validateNationalNumberLength(e164);
484	        return e164;
485	    }
486	
487	    /**
488	     * Rejects an E.164 telephone whose national number does not have the exact length its country
489	     * calling code requires. The digits after the leading '+' are split into the longest matching
490	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
491	     * code is known and the national number's length differs from the required count the telephone is
492	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
493	     *
494	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
495	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
496	     */
497	    private void validateNationalNumberLength(String e164) {
498	        String digits = e164.substring(1);
499	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
500	            String countryCode = digits.substring(0, codeLength);
501	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
502	            if (requiredNationalLength != null) {
503	                int nationalLength = digits.length() - codeLength;
504	                if (nationalLength != requiredNationalLength) {
505	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
506	                }
507	                return;
508	            }
509	        }
510	    }
511	
512	    /**
513	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
514	     * left unset. When a value is present it must be a syntactically valid address; the normalized
515	     * form stored and returned is the value lower-cased.
516	     *
517	     * @param email the raw email value from the request, or {@code null} when none was supplied
518	     * @return the lower-cased email, or {@code null} when no email was supplied
519	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
520	     */
521	    private String normalizeEmail(String email) {
522	        if (email == null || email.isBlank()) {
523	            return null;
524	        }
525	        if (!EMAIL_PATTERN.matcher(email).matches()) {
526	            throw new InvalidOwnerFieldsException(List.of("email"));
527	        }
528	        return email.toLowerCase(Locale.ROOT);
529	    }
530	
531	    /**
532	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
533	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
534	     * When present it must be exactly four digits and, when the owner's city maps to a known region
535	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
536	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
537	     * region accepts any four-digit postcode.
538	     *
539	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
540	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
541	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
542	     *         for the city's region
543	     */
544	    private void validatePostcode(String city, String postcode) {
545	        if (postcode == null || postcode.isBlank()) {
546	            return;
547	        }
548	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
549	            throw new InvalidOwnerFieldsException(List.of("postcode"));
550	        }
551	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
552	        if (range == null) {
553	            return;
554	        }
555	        int value = Integer.parseInt(postcode);
556	        if (value < range[0] || value > range[1]) {
557	            throw new InvalidOwnerFieldsException(List.of("postcode"));
558	        }
559	    }
560	
561	    /**
562	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
563	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
564	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
565	     * normalized form is what gets stored, returned and used for every address comparison (the
566	     * required-field check, household duplicate detection and the shared household id).
567	     *
568	     * @param address the raw address value from the request, or {@code null}
569	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
570	     */
571	    private String normalizeAddress(String address) {
572	        if (address == null) {
573	            return "";
574	        }
575	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
576	        if (collapsed.isEmpty()) {
577	            return "";
578	        }
579	        String[] tokens = collapsed.split(" ");
580	        for (int i = 0; i < tokens.length; i++) {
581	            switch (tokens[i]) {
582	                case "ST" -> tokens[i] = "STREET";
583	                case "RD" -> tokens[i] = "ROAD";
584	                case "AVE" -> tokens[i] = "AVENUE";
585	                default -> { }
586	            }
587	        }
588	        return String.join(" ", tokens);
589	    }
590	
591	    /**
592	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
593	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
594	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
595	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
596	     * so two members of one household with different telephones have different keys and are both
597	     * allowed; only an owner whose entire key is identical is a duplicate.
598	     *
599	     * @param owner the owner being created, with its telephone, email and householdId already resolved
600	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
601	     */
602	    private void rejectDuplicateIdentity(Owner owner) {
603	        String identityKey = owner.getIdentityKey();
604	        boolean inUse = this.clinicService.findAllOwners().stream()
605	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
606	        if (inUse) {
607	            throw new DuplicateOwnerIdentityException(identityKey);
608	        }
609	    }
610	
611	    /**
612	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
613	     * last name and a normalized address: last names are compared case-insensitively after whitespace
614	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
615	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
616	     * abbreviation still count as the same household.
617	     * <p>
618	     * When the owner's last name and address already belong to at least one other owner and
619	     * {@code sharesHousehold} is true, every member of the household - the existing owners and this
620	     * joiner - is assigned the same stable {@code householdId}, which is returned on read and forms
621	     * the third component of the {@code identityKey}. When {@code sharesHousehold} is not true, or no
622	     * other owner shares the last name and address, no identifier is assigned. Household membership no
623	     * longer rejects a create on its own; duplicates are detected solely through the identity key.
624	     *
625	     * @param owner the owner being created
626	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
627	     */
628	    /**
629	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
630	     * household member count} for the response.
631	     *
632	     * @param owner the owner to map
633	     * @return the mapped owner DTO
634	     */
635	    private OwnerDto toOwnerDto(Owner owner) {
636	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
637	        return ownerMapper.toOwnerDto(owner);
638	    }
639	
640	    /**
641	     * Counts the members of the given owner's household - the owners that share this owner's
642	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
643	     * is {@code null}) is its own sole member, so the count is one.
644	     *
645	     * @param owner the owner whose household is being sized
646	     * @return the number of owners sharing this owner's household (one when it has no household)
647	     */
648	    private int countHouseholdMembers(Owner owner) {
649	        String householdId = owner.getHouseholdId();
650	        if (householdId == null) {
651	            return 1;
652	        }
653	        return (int) this.clinicService.findAllOwners().stream()
654	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
655	            .count();
656	    }
657	
658	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
659	        String lastName = normalizeHouseholdField(owner.getLastName());
660	        String address = normalizeAddress(owner.getAddress());
661	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
662	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
663	                && normalizeAddress(existing.getAddress()).equals(address))
664	            .toList();
665	        if (housemates.isEmpty()) {
666	            return;
667	        }
668	        if (!Boolean.TRUE.equals(sharesHousehold)) {
669	            return;
670	        }
671	        String householdId = generateHouseholdId(lastName, address);
672	        owner.setHouseholdId(householdId);
673	        for (Owner housemate : housemates) {
674	            if (!householdId.equals(housemate.getHouseholdId())) {
675	                housemate.setHouseholdId(householdId);
676	                this.clinicService.saveOwner(housemate);
677	            }
678	        }
679	    }
680	
681	    /**
682	     * Builds the stable identifier shared by the members of one household. It is derived purely from
683	     * the normalized last name and address, so every owner of a given household deterministically
684	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
685	     * two normalized fields joined by a single space.
686	     *
687	     * @param normalizedLastName the household's last name, already normalized for comparison
688	     * @param normalizedAddress the household's address, already normalized for comparison
689	     * @return the shared household identifier
690	     */
691	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
692	        String key = normalizedLastName + '�' + normalizedAddress;
693	        try {
694	            byte[] digest = MessageDigest.getInstance("SHA-256")
695	                .digest(key.getBytes(StandardCharsets.UTF_8));
696	            StringBuilder hex = new StringBuilder();
697	            for (byte b : digest) {
698	                hex.append(String.format("%02X", b));
699	                if (hex.length() >= 12) {
700	                    break;
701	                }
702	            }
703	            return hex.substring(0, 12);
704	        } catch (NoSuchAlgorithmException e) {
705	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
706	        }
707	    }
708	
709	    /**
710	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
711	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
712	     * the owner's normalized telephone and last name.
713	     *
714	     * @param input the string to digest
715	     * @param length the number of leading upper-case hex characters to return
716	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
717	     */
718	    private String sha256UpperHex(String input, int length) {
719	        try {
720	            byte[] digest = MessageDigest.getInstance("SHA-256")
721	                .digest(input.getBytes(StandardCharsets.UTF_8));
722	            StringBuilder hex = new StringBuilder();
723	            for (byte b : digest) {
724	                hex.append(String.format("%02X", b));
725	                if (hex.length() >= length) {
726	                    break;
727	                }
728	            }
729	            return hex.substring(0, length);
730	        } catch (NoSuchAlgorithmException e) {
731	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
732	        }
733	    }
734	
735	    /**
736	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
737	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
738	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
739	     * expands common abbreviations.
740	     *
741	     * @param value the raw last name, or {@code null}
742	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
743	     */
744	    private String normalizeHouseholdField(String value) {
745	        if (value == null) {
746	            return "";
747	        }
748	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
749	    }
750	}
